playbackMultiplayerReplay(value: unknown, applyFrame: (frame: Readonly<MultiplayerReplayFrame>) => void): MultiplayerReplayPlayback {
  const replay = this.normalizeMultiplayerReplay(value)
  this.requireMultiplayerCompatibility(replay, 'Multiplayer replay', true)
  let previousTick = -1
  for (const frame of replay.frames) {
    if (frame.tick <= previousTick) throw new Error('Multiplayer replay ticks must be strictly increasing.')
    applyFrame(Object.freeze({ ...frame, inputs: frame.inputs.map(/** 构造并返回记录 { peerId: item.peerId, input: cloneNetworkInput(item.input) }，字段按当前实参及捕获状态求值。 */ item => ({ peerId: item.peerId, input: cloneNetworkInput(item.input) })) }))
    previousTick = frame.tick
  }
  return { frames: replay.frames.length, firstTick: replay.frames[0]?.tick ?? null, lastTick: replay.frames[replay.frames.length - 1]?.tick ?? null, checksum: networkChecksum(replay.frames) }
}

multiplayerSavePayload(document: Omit<MultiplayerSaveDocument, 'checksum'> | MultiplayerSaveDocument): unknown {
  return { format: document.format, version: document.version, engineVersion: document.engineVersion, protocolVersion: document.protocolVersion, schemaVersion: document.schemaVersion, sessionName: document.sessionName, tick: document.tick, entities: document.entities }
}

legacyMultiplayerSavePayload(document: MultiplayerSaveDocument): unknown {
  return { format: document.format, version: document.version, engineVersion: document.engineVersion, protocolVersion: document.protocolVersion, schemaVersion: document.schemaVersion, sessionName: document.sessionName, tick: document.tick, savedAt: document.savedAt, entities: document.entities }
}

exportMultiplayerSave(entities: Entity[], tick: number): MultiplayerSaveDocument {
    this.requireEntities(entities)
  const definitions = new Set(this.configuration.networking.replicatedEntities.map(/* 返回 item.entityUuid 的当前值。 */ item => item.entityUuid)), source = entities.filter(/* 调用 definitions.has(entity.uuid) 并返回调用结果。 */ entity => definitions.has(entity.uuid)).slice(0, 2_000).map(/** 结构说明（自动提取）：map 回调；输入 entity；直接调用 worldTransform、finiteNumber、validateMultiplayerSaveState。 */ entity => {
    const transform = worldTransform(entity, entities)
    const state = { enabled: entity.enabled, position: [finiteNumber(transform.position.x), finiteNumber(transform.position.y)] as [number, number], rotation: finiteNumber(transform.rotation), scale: [finiteNumber(transform.scale.x, 1), finiteNumber(transform.scale.y, 1)] as [number, number], velocity: [finiteNumber(entity.velocity.x), finiteNumber(entity.velocity.y)] as [number, number], angularVelocity: finiteNumber(entity.angularVelocity) }
    this.validateMultiplayerSaveState(state, entity.uuid)
    return { uuid: entity.uuid, ...state }
  }).sort(/* 调用 a.uuid.localeCompare(b.uuid) 并返回调用结果。 */ (a, b) => a.uuid.localeCompare(b.uuid))
  const deterministicTick = this.integer(tick, 0, 0, 0x7fff_ffff)
  const base = { format: 'nova-multiplayer-save' as const, version: 1 as const, engineVersion: NOVA_ENGINE_VERSION, protocolVersion: 2 as const, schemaVersion: this.configuration.networking.schemaVersion, sessionName: this.configuration.networking.sessionName, tick: deterministicTick, savedAt: new Date(deterministicTick * 1_000).toISOString(), entities: source }
  return { ...base, checksum: networkChecksum(this.multiplayerSavePayload(base)) }
}

importMultiplayerSave(value: unknown, entities: Entity[], propertyMasks?: ReadonlyMap<string, readonly string[]>): { tick: number; restored: number } {
    this.requireEntities(entities)
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Multiplayer save must be an object.')
  const source = value as Partial<MultiplayerSaveDocument>
  if (source.format !== 'nova-multiplayer-save' || source.version !== 1 || source.protocolVersion !== 2 || typeof source.checksum !== 'string' || !/^[a-f0-9]{24}$/i.test(source.checksum) || !Array.isArray(source.entities)) throw new Error('Unsupported multiplayer save format or protocol.')
  this.requireMultiplayerCompatibility(source, 'Multiplayer save', true)
  if (!Number.isSafeInteger(source.tick) || Number(source.tick) < 0 || Number(source.tick) > 0x7fff_ffff) throw new Error('Multiplayer save tick is invalid.')
  if (typeof source.savedAt !== 'string' || !source.savedAt || Number.isNaN(Date.parse(source.savedAt))) throw new Error('Multiplayer save timestamp is invalid.')
  if (source.entities.length > 2_000) throw new Error('Multiplayer save exceeds the 2,000-entity bound.')
  const document = source as MultiplayerSaveDocument, deterministicChecksum = networkChecksum(this.multiplayerSavePayload(document)), legacyChecksum = networkChecksum(this.legacyMultiplayerSavePayload(document))
  if (deterministicChecksum !== source.checksum && legacyChecksum !== source.checksum) throw new Error('Multiplayer save checksum mismatch.')
  const staged: MultiplayerSaveStage[] = [], seen = new Set<string>()
  for (const raw of source.entities) {
    if (!raw || typeof raw !== 'object' || typeof raw.uuid !== 'string' || seen.has(raw.uuid)) throw new Error('Multiplayer save contains an invalid or duplicate entity identity.')
    seen.add(raw.uuid)
    if (typeof raw.enabled !== 'boolean') throw new Error(`Multiplayer save state for ${raw.uuid.slice(0, 128)} is invalid.`)
    this.validateMultiplayerSaveState(raw, raw.uuid.slice(0, 128))
    const entity = entities.find(/* 比较 candidate.uuid 与 raw.uuid，返回严格相等的判断结果。 */ candidate => candidate.uuid === raw.uuid); if (!entity) continue
    staged.push({ entity, enabled: raw.enabled, position: [raw.position[0], raw.position[1]], rotation: raw.rotation, scale: [raw.scale[0], raw.scale[1]], velocity: [raw.velocity[0], raw.velocity[1]], angularVelocity: raw.angularVelocity })
  }
  const ordered = this.parentFirstSaveStages(staged)
  const backupByUuid = new Map(staged.map(/** 结构说明（自动提取）：staged.map 回调；输入 item；直接调用 worldTransform。 */ item => { const transform = worldTransform(item.entity, entities); return [item.entity.uuid, { entity: item.entity, enabled: item.entity.enabled, position: [transform.position.x, transform.position.y] as [number, number], rotation: transform.rotation, scale: [transform.scale.x, transform.scale.y] as [number, number], velocity: [item.entity.velocity.x, item.entity.velocity.y] as [number, number], angularVelocity: item.entity.angularVelocity }] as const }))
  const backup = ordered.map(/** 结构说明（自动提取）：ordered.map 回调；输入 item；直接调用 backupByUuid.get；返回表达式求值结果。 */ item => backupByUuid.get(item.entity.uuid)!)
  // Network baselines obey the same authored fields as live snapshots. Manual saves remain complete.
  if (propertyMasks) for (const item of ordered) {
    const previous = backupByUuid.get(item.entity.uuid)!, properties = propertyMasks.get(item.entity.uuid) ?? []
    if (!properties.includes('transform')) item.position = previous.position
    if (!properties.includes('rotation')) item.rotation = previous.rotation
    if (!properties.includes('velocity')) item.velocity = previous.velocity
    item.enabled = previous.enabled; item.scale = previous.scale; item.angularVelocity = previous.angularVelocity
  }
  try { for (const item of ordered) { setWorldTransform(item.entity, { position: { x: item.position[0], y: item.position[1] }, rotation: item.rotation, scale: { x: item.scale[0], y: item.scale[1] } }, entities); item.entity.enabled = item.enabled; item.entity.velocity = { x: item.velocity[0], y: item.velocity[1] }; item.entity.angularVelocity = item.angularVelocity } }
  catch (error) { for (const item of backup) { setWorldTransform(item.entity, { position: { x: item.position[0], y: item.position[1] }, rotation: item.rotation, scale: { x: item.scale[0], y: item.scale[1] } }, entities); item.entity.enabled = item.enabled; item.entity.velocity = { x: item.velocity[0], y: item.velocity[1] }; item.entity.angularVelocity = item.angularVelocity }; throw error }
  return { tick: this.integer(source.tick, 0, 0, 0x7fff_ffff), restored: staged.length }
}

networkDiagnosticCapture(state: Record<string, unknown>, events: unknown[], packetSummaries: unknown[]): string {
  const SENSITIVE_DIAGNOSTIC_KEY = /(?:endpoint|bind.?address|password|passphrase|secret|(?:^|[_-])token|access[_-]?token|api[_-]?key|private[_-]?key|authorization|cookie|session[_-]?key)/i
  const seen = new WeakSet<object>(), budget = { remaining: 24_000 }
  const sanitize = /** 结构说明（自动提取）：sanitize；输入 value、depth；直接调用 Number.isFinite、value.slice、seen.has、seen.add、Array.isArray 等；写入 entries；返回路径包含 value。 */ (value: unknown, depth = 0): unknown => {
    if (budget.remaining-- <= 0 || depth > 10) return null
    if (value === null || typeof value === 'boolean') return value
    if (typeof value === 'number') return Number.isFinite(value) ? value : null
    if (typeof value === 'string') return value.slice(0, 65_536)
    if (typeof value !== 'object') return null
    if (seen.has(value)) return null
    seen.add(value)
    if (Array.isArray(value)) return value.slice(-1_000).map(/* 调用 sanitize(item, depth + 1) 并返回调用结果。 */ item => sanitize(item, depth + 1))
    let entries: Array<[string, unknown]> = []
    try { entries = Object.entries(value as Record<string, unknown>) } catch { return null }
    return Object.fromEntries(entries
      .filter(/** 结构说明（自动提取）：entries.filter 回调；输入 [key]；直接调用 utf8Bytes、SENSITIVE_DIAGNOSTIC_KEY.test；返回表达式求值结果。 */ ([key]) => key.length > 0 && utf8Bytes(key) <= 128 && !SENSITIVE_DIAGNOSTIC_KEY.test(key) && key !== 'events' && key !== 'packetSummaries')
      .slice(0, 1_000)
      .map(/* 返回按声明顺序构造的数组 [key, sanitize(item, depth + 1)]。 */ ([key, item]) => [key, sanitize(item, depth + 1)]))
  }
  const safeState = sanitize(state) as Record<string, unknown>
  const document = { format: 'nova-network-diagnostics', version: 1, engineVersion: NOVA_ENGINE_VERSION, protocolVersion: 2, capturedAt: new Date(this.ports.wallNow()).toISOString(), session: { mode: this.configuration.networking.sessionMode, role: this.configuration.networking.role, schemaVersion: this.configuration.networking.schemaVersion, channelIds: this.configuration.networking.channels.map(/* 返回 channel.id 的当前值。 */ channel => channel.id) }, state: safeState, events: events.slice(-500).map(/* 调用 sanitize(item) 并返回调用结果。 */ item => sanitize(item)), packets: packetSummaries.slice(-1_000).map(/* 调用 sanitize(item) 并返回调用结果。 */ item => sanitize(item)) }
  const error = validateNetworkValue(document)
  if (error) throw new Error(error)
  return `${stableNetworkJson(document)}\n`
}

}

import type { NetworkProjectSettings, ReplicatedEntityDefinition } from './networkSessionContracts'

export interface NetworkTransportContract {
  readonly kind: 'adapter'
  connect(onMessage: (source: string, peer: string) => void, onState: (state: string) => void): Promise<void>
  send(source: string, target?: string): Promise<void>
  close(): Promise<void>
}

export interface NetworkTransportReview {
  id: string
  label: string
  version: string
  publisher: string
  sha256: string
  reviewedBy: 'Whitelist'
  permissions: Array<'network.client' | 'network.listen'>
  encrypted: boolean
  documentationUrl: string
  securityUrl: string
}

export interface ReviewedNetworkTransportAdapter {
  review: NetworkTransportReview
  create(settings: Readonly<NetworkProjectSettings>): NetworkTransportContract
}

export interface NetworkAuthenticationContext {
  sessionId: string
  sender: string
  epoch: string
  nonce: string
  issuedAt: number
  packetChecksum: string
}

export interface NetworkAuthenticationProvider {
  id: string
  label: string
  createProof(context: NetworkAuthenticationContext): string
  verifyProof(context: NetworkAuthenticationContext, proof: string): boolean
}

export interface NetworkSecurityEnvelope {
  epoch: string
  nonce: string
  issuedAt: number
  proof: string
}

export interface NetworkReplayDecision { accepted: boolean; reason: '' | 'missing-envelope' | 'expired' | 'future' | 'duplicate' | 'window-full' }

export interface NetworkInterestView { peerId: string; center: [number, number]; radius: number; sceneUuid: string; updatedAt: number }

export interface NetworkRollbackEntry { tick: number; peerId: string; checksumBefore: string; checksumAfter: string; replayedInputs: number; correction: number; reason: string }

export interface NetworkReplicationDiff { tick: number; peerId: string; entityUuid: string; fields: string[]; error: number; authority: string }

export interface NetworkPlayInstance { id: string; role: 'host' | 'client'; playerName: string; sessionName: string; logScope: string; inspectorId: string }

const transportAdapters = new Map<string, ReviewedNetworkTransportAdapter>()

const authenticationProviders = new Map<string, NetworkAuthenticationProvider>()

export function safeId(value: string, maximum = 80): string { return value.trim().replace(/[^a-zA-Z0-9_.-]/g, '_').slice(0, maximum) }

function https(value: string): boolean { return /^https:\/\/[^\s]+$/i.test(value) }

export function transportReviewIssues(review: NetworkTransportReview): string[] {
  const issues: string[] = []
  if (!/^[a-z0-9]+(?:[.-][a-z0-9]+)+$/.test(review.id)) issues.push('Adapter ID must be reverse-domain style.')
  if (!/^\d+\.\d+\.\d+$/.test(review.version)) issues.push('Adapter version must use semantic versioning.')
  if (!review.publisher.trim() || review.reviewedBy !== 'Whitelist') issues.push('Adapter publisher review is missing.')
  if (!/^[a-f0-9]{64}$/.test(review.sha256)) issues.push('Adapter SHA-256 is invalid.')
  if (!review.permissions.includes('network.client') || review.permissions.some(/* 先计算 permission !== 'network.client'；仅当其为真值时求右侧 permission !== 'network.listen'，返回短路求值结果。 */ permission => permission !== 'network.client' && permission !== 'network.listen')) issues.push('Adapter permissions are missing or exceed networking scope.')
  if (!https(review.documentationUrl) || !https(review.securityUrl)) issues.push('Adapter documentation and security policy must use HTTPS.')
  return issues
}

export function registerReviewedNetworkTransport(adapter: ReviewedNetworkTransportAdapter): () => void {
  const issues = transportReviewIssues(adapter.review)
  if (issues.length) throw new Error(`Network transport adapter rejected: ${issues.join(' ')}`)
  if (transportAdapters.has(adapter.review.id)) throw new Error(`Network transport adapter ${adapter.review.id} is already registered.`)
  transportAdapters.set(adapter.review.id, adapter)
  return /* 调用 transportAdapters.delete(adapter.review.id) 并返回调用结果。 */ () => transportAdapters.delete(adapter.review.id)
}

export function reviewedNetworkTransports(): ReadonlyArray<NetworkTransportReview> {
  return [...transportAdapters.values()].map(/* 调用 Object.freeze({ ...adapter.review, permissions: [...adapter.review.permissions] }) 并返回调用结果。 */ adapter => Object.freeze({ ...adapter.review, permissions: [...adapter.review.permissions] })).sort(/* 调用 a.label.localeCompare(b.label) 并返回调用结果。 */ (a, b) => a.label.localeCompare(b.label))
}

export function createReviewedNetworkTransport(id: string, settings: Readonly<NetworkProjectSettings>): NetworkTransportContract | null {
  const adapter = transportAdapters.get(id)
  if (!adapter || ((settings.role === 'host' || settings.role === 'server') && !adapter.review.permissions.includes('network.listen'))) return null
  return adapter.create(settings)
}

export function registerNetworkAuthenticationProvider(provider: NetworkAuthenticationProvider): () => void {
  const id = safeId(provider.id)
  if (!id || id !== provider.id || !provider.label.trim()) throw new Error('Authentication provider identity is invalid.')
  if (authenticationProviders.has(id)) throw new Error(`Authentication provider ${id} is already registered.`)
  authenticationProviders.set(id, provider)
  return /* 调用 authenticationProviders.delete(id) 并返回调用结果。 */ () => authenticationProviders.delete(id)
}

export function networkAuthenticationProviders(): ReadonlyArray<{ id: string; label: string }> {
  return [...authenticationProviders.values()].map(/** 构造并返回记录 { id: provider.id, label: provider.label }，字段按当前实参及捕获状态求值。 */ provider => ({ id: provider.id, label: provider.label })).sort(/* 调用 a.label.localeCompare(b.label) 并返回调用结果。 */ (a, b) => a.label.localeCompare(b.label))
}

export function createAuthenticationProof(providerId: string, context: NetworkAuthenticationContext): string {
  const provider = authenticationProviders.get(providerId)
  if (!provider) throw new Error(`Authentication provider ${providerId || '(none)'} is not registered.`)
  const proof = provider.createProof(Object.freeze({ ...context })).trim()
  if (!proof || proof.length > 512) throw new Error('Authentication provider returned an empty or oversized proof.')
  return proof
}

export function verifyAuthenticationProof(providerId: string, context: NetworkAuthenticationContext, proof: string): boolean {
  const provider = authenticationProviders.get(providerId)
  if (!provider || !proof || proof.length > 512) return false
  try { return provider.verifyProof(Object.freeze({ ...context }), proof) === true } catch { return false }
}

export class NetworkReplayProtectionWindow {
  private readonly seen = new Map<string, Map<string, number>>()

  /** 结构说明（自动提取）：accept；输入 sender、envelope、now、maximumAgeMs、maximumEntries、required、commit；直接调用 Number.isSafeInteger、safeId、seen.get、Map、entries.delete 等；包含循环处理。 */ accept(sender: string, envelope: NetworkSecurityEnvelope | undefined, now: number, maximumAgeMs: number, maximumEntries: number, required: boolean, commit = true): NetworkReplayDecision {
    if (!envelope) return required ? { accepted: false, reason: 'missing-envelope' } : { accepted: true, reason: '' }
    if (!envelope.epoch || envelope.epoch.length > 80 || !envelope.nonce || envelope.nonce.length > 120 || !Number.isSafeInteger(envelope.issuedAt)) return { accepted: false, reason: 'expired' }
    const age = now - envelope.issuedAt
    if (age < -5_000) return { accepted: false, reason: 'future' }
    if (age > maximumAgeMs) return { accepted: false, reason: 'expired' }
    const key = `${safeId(sender)}:${safeId(envelope.epoch)}`, entries = this.seen.get(key) ?? new Map<string, number>()
    for (const [nonce, issuedAt] of entries) if (now - issuedAt > maximumAgeMs) entries.delete(nonce)
    if (entries.has(envelope.nonce)) return { accepted: false, reason: 'duplicate' }
    if (entries.size >= maximumEntries) return { accepted: false, reason: 'window-full' }
    if (commit) { entries.set(envelope.nonce, envelope.issuedAt); this.seen.set(key, entries) }
    while (this.seen.size > 128) this.seen.delete(this.seen.keys().next().value ?? '')
    return { accepted: true, reason: '' }
  }

  /** 结构说明（自动提取）：clearPeer；输入 sender；直接调用 seen.keys、key.startsWith、safeId、seen.delete；包含循环处理。 */ clearPeer(sender: string): void { for (const key of this.seen.keys()) if (key.startsWith(`${safeId(sender)}:`)) this.seen.delete(key) }
  /** 执行时调用 this.seen.clear()；不显式返回调用结果。 */ clear(): void { this.seen.clear() }
}

export class NetworkAuthorityTable {
  private owners = new Map<string, string>()
  private authored = new Map<string, string>()
  /** 结构说明（自动提取）：initialize；输入 definitions、localPeerId、role；直接调用 clear、synchronize。 */ initialize(definitions: readonly ReplicatedEntityDefinition[], localPeerId: string, role: string): void {
    this.clear(); this.synchronize(definitions, localPeerId, role)
  }
  /** 结构说明（自动提取）：synchronize；输入 definitions、localPeerId、role；直接调用 Set、allowed.add、JSON.stringify、authored.get、authored.set 等；写入 changed；返回路径包含 changed；包含循环处理。 */ synchronize(definitions: readonly ReplicatedEntityDefinition[], localPeerId: string, role: string): boolean {
    let changed = false
    const allowed = new Set<string>()
    for (const definition of definitions) {
      allowed.add(definition.entityUuid)
      const identity = JSON.stringify([definition.authority, definition.ownerPeerId, role, localPeerId])
      if (this.authored.get(definition.entityUuid) === identity) continue
      this.authored.set(definition.entityUuid, identity)
      this.owners.set(definition.entityUuid, definition.authority === 'owner' && definition.ownerPeerId ? definition.ownerPeerId : role === 'server' || role === 'host' ? localPeerId : '')
      changed = true
    }
    for (const uuid of this.authored.keys()) if (!allowed.has(uuid)) { this.authored.delete(uuid); this.owners.delete(uuid); changed = true }
    return changed
  }
  /* 当 this.owners.get(entityUuid) 为 null 或 undefined 时返回 ''，否则保留左侧值。 */ owner(entityUuid: string): string { return this.owners.get(entityUuid) ?? '' }
  /** 结构说明（自动提取）：entries；无显式参数；直接调用 sort、map。 */ entries(): Array<{ entityUuid: string; ownerPeerId: string }> { return [...this.owners].map(/** 构造并返回记录 { entityUuid, ownerPeerId }，字段按当前实参及捕获状态求值。 */ ([entityUuid, ownerPeerId]) => ({ entityUuid, ownerPeerId })).sort(/* 调用 a.entityUuid.localeCompare(b.entityUuid) 并返回调用结果。 */ (a, b) => a.entityUuid.localeCompare(b.entityUuid)) }
  /** 结构说明（自动提取）：restore；输入 entries、definitions；直接调用 Array.isArray、Set、definitions.map、Map、safeId 等；写入 owners；包含循环处理。 */ restore(entries: readonly { entityUuid: string; ownerPeerId: string }[], definitions: readonly ReplicatedEntityDefinition[]): boolean {
    if (!Array.isArray(entries) || entries.length > 2_000) return false
    const allowed = new Set(definitions.map(/* 返回 definition.entityUuid 的当前值。 */ definition => definition.entityUuid)), staged = new Map<string, string>()
    for (const entry of entries) {
      if (!entry || typeof entry !== 'object' || Array.isArray(entry) || typeof entry.entityUuid !== 'string' || typeof entry.ownerPeerId !== 'string') return false
      const entityUuid = safeId(entry.entityUuid, 128), ownerPeerId = entry.ownerPeerId ? safeId(entry.ownerPeerId, 80) : ''
      if (!entityUuid || entityUuid !== entry.entityUuid || !allowed.has(entityUuid) || (entry.ownerPeerId && ownerPeerId !== entry.ownerPeerId) || staged.has(entityUuid)) return false
      staged.set(entityUuid, ownerPeerId)
    }
    if (staged.size !== allowed.size) return false
    this.owners = staged; return true
  }
  /** 结构说明（自动提取）：transfer；输入 entityUuid、targetPeerId；直接调用 owners.has、safeId、owners.set。 */ transfer(entityUuid: string, targetPeerId: string): boolean { if (!this.owners.has(entityUuid) || !safeId(targetPeerId)) return false; this.owners.set(entityUuid, safeId(targetPeerId)); return true }
  /** 结构说明（自动提取）：releasePeer；输入 peerId、authorityPeerId；直接调用 owners.set、changed.push、changed.sort；包含循环处理。 */ releasePeer(peerId: string, authorityPeerId: string): string[] { const changed: string[] = []; for (const [entityUuid, owner] of this.owners) if (owner === peerId) { this.owners.set(entityUuid, authorityPeerId); changed.push(entityUuid) }; return changed.sort() }
  /** 结构说明（自动提取）：clear；无显式参数；直接调用 owners.clear、authored.clear。 */ clear(): void { this.owners.clear(); this.authored.clear() }
}

export function entityRelevantToPeer(definition: ReplicatedEntityDefinition, position: [number, number], view: NetworkInterestView | undefined, enabled: boolean): boolean {
  if (!enabled || definition.alwaysRelevant || !view) return true
  if (definition.sceneUuid && view.sceneUuid && definition.sceneUuid !== view.sceneUuid) return false
  const radius = Math.max(0, Math.min(view.radius, definition.interestRadius || view.radius))
  return Math.hypot(position[0] - view.center[0], position[1] - view.center[1]) <= radius
}

export class NetworkTimeline<T> {
  private values: T[] = []
  /** 结构说明（自动提取）：匿名回调；输入 capacity；空实现，不执行额外操作。 */ constructor(private readonly capacity: number) {}
  /** 结构说明（自动提取）：push；输入 value；直接调用 values.push、values.splice。 */ push(value: T): void { this.values.push(value); if (this.values.length > this.capacity) this.values.splice(0, this.values.length - this.capacity) }
  /* 调用 structuredClone(this.values) 并返回调用结果。 */ snapshot(): T[] { return structuredClone(this.values) }
  /** 执行时调用 this.values.splice(0)；不显式返回调用结果。 */ clear(): void { this.values.splice(0) }
}

export function createNetworkPlayPlan(count: number, sessionName: string): NetworkPlayInstance[] {
  const peers = Math.max(2, Math.min(8, Math.round(count) || 2)), session = sessionName.trim().slice(0, 80) || 'Local game'
  return Array.from({ length: peers }, /** 结构说明（自动提取）：Array.from 回调；输入 _、index；返回表达式求值结果。 */ (_, index) => ({ id: `peer-${index + 1}`, role: index === 0 ? 'host' : 'client', playerName: index === 0 ? 'Host' : `Client ${index}`, sessionName: session, logScope: `network-${index + 1}`, inspectorId: `network-peer-${index + 1}` }))
}

export function networkEncryptionGuidance(settings: Readonly<NetworkProjectSettings>, adapterEncrypted = false): { protected: boolean; severity: 'info' | 'warning' | 'error'; message: string } {
  const protectedTransport = settings.sessionMode === 'local' || adapterEncrypted || (settings.transport === 'websocket' && /^wss:\/\//i.test(settings.endpoint))
  if (protectedTransport) return { protected: true, severity: 'info', message: settings.sessionMode === 'local' ? 'Local lobby traffic stays on the same device and origin.' : 'The selected adapter declares encrypted transport.' }
  if (settings.security.requireEncryption) return { protected: false, severity: 'error', message: 'Encryption is required, but the selected direct transport is not encrypted. Use WSS or a reviewed encrypted adapter.' }
  return { protected: false, severity: 'warning', message: 'Direct traffic is not encrypted. Use WSS, a reviewed encrypted adapter, or an independently reviewed secure tunnel.' }
}

import type { NetworkTransport, NetworkTransportContext } from '../runtime/networkSessionContracts'
import { stableNetworkJson } from '../runtime/networkProtocol'

export class LocalLobbyTransport implements NetworkTransport {
  constructor(private readonly context:NetworkTransportContext) {}

  readonly kind = 'local-loopback' as const
  private channel: BroadcastChannel | null = null
  /** 结构说明（自动提取）：connect；输入 onMessage、onState；直接调用 Error、BroadcastChannel、networkSessionId、onState；写入 channel、channel.onmessage、channel.onmessageerror；包含显式抛错路径。 */ async connect(onMessage: (source: string, peer: string) => void, onState: (state: string) => void): Promise<void> {
    if (typeof BroadcastChannel === 'undefined') throw new Error('This runtime does not provide local lobby channels.')
    this.channel = new BroadcastChannel(`nova-a-${this.context.networkSessionId()}`)
    this.channel.onmessage = /** 结构说明（自动提取）：匿名回调；输入 event；直接调用 onMessage。 */ event => { const value = event.data as { source?: unknown; peer?: unknown; target?: unknown }; if (typeof value?.source === 'string' && typeof value.peer === 'string' && value.peer !== this.context.networkingState.localPeerId && (typeof value.target !== 'string' || !value.target || value.target === this.context.networkingState.localPeerId)) onMessage(value.source, value.peer) }
    this.channel.onmessageerror = /* 调用 onState('Local lobby message could not be decoded.') 并返回调用结果。 */ () => onState('Local lobby message could not be decoded.')
    onState('connected')
  }
  /** 结构说明（自动提取）：send；输入 source、target；直接调用 Error、channel.postMessage；包含显式抛错路径。 */ async send(source: string, target = ''): Promise<void> { if (!this.channel) throw new Error('Local lobby is not open.'); this.channel.postMessage({ source, peer: this.context.networkingState.localPeerId, target }) }
  /** 结构说明（自动提取）：close；无显式参数；直接调用 channel.close；写入 channel。 */ async close(): Promise<void> { this.channel?.close(); this.channel = null }
}

export class WebSocketTransport implements NetworkTransport {
  constructor(private readonly context:NetworkTransportContext) {}

  readonly kind = 'websocket' as const
  private socket: WebSocket | null = null
  private cancelOpening: (() => void) | null = null
  /** 结构说明（自动提取）：connect；输入 onMessage、onState；直接调用 test、Error、Promise；等待异步结果；包含显式抛错路径。 */ async connect(onMessage: (source: string, peer: string) => void, onState: (state: string) => void): Promise<void> {
    if (!/^wss?:\/\//i.test(this.context.configuration.networking.endpoint)) throw new Error('WebSocket endpoint must begin with ws:// or wss://.')
    await new Promise<void>(/** 结构说明（自动提取）：匿名回调；输入 resolve、reject；直接调用 WebSocket、globalThis.setTimeout；写入 socket、socket.onopen、socket.onmessage、socket.onerror 等。 */ (resolve, reject) => {
      const socket = new WebSocket(this.context.configuration.networking.endpoint); this.socket = socket
      let settled = false
      /** 握手只完成一次；所有成功、失败和主动停止路径均释放超时。 */
      const finish = (error?: Error): void => {
        if (settled) return
        settled = true; clearTimeout(timeout); this.cancelOpening = null
        if (error) reject(error); else resolve()
      }
      const timeout = globalThis.setTimeout(/** 超时必须拒绝当前握手而非遗留挂起承诺。 */ () => finish(new Error('WebSocket connection timed out.')), 10_000)
      this.cancelOpening = /** 主动停止立刻结束尚未完成的握手。 */ () => finish(new DOMException('WebSocket connection cancelled.', 'AbortError'))
      socket.onopen = /** 结构说明（自动提取）：匿名回调；无显式参数；直接调用 clearTimeout、onState、resolve。 */ () => { if (settled || this.socket !== socket) return; onState('connected'); finish() }
      socket.onmessage = /** 结构说明（自动提取）：匿名回调；输入 event；直接调用 JSON.parse、test、onMessage。 */ event => {
        const source = typeof event.data === 'string' ? event.data : ''
        try {
          const route = JSON.parse(source) as { format?: unknown; version?: unknown; target?: unknown; sender?: unknown; payload?: unknown }
          if (route.format === 'nova-network-route' && route.version === 1 && typeof route.payload === 'string' && route.payload.length <= this.context.configuration.networking.maximumPacketBytes && typeof route.sender === 'string' && /^[A-Za-z0-9_.-]{1,80}$/.test(route.sender) && (route.target === '' || route.target === this.context.networkingState.localPeerId)) { onMessage(route.payload, route.sender); return }
        } catch { /* A one-peer/raw broker remains backwards compatible. */ }
        onMessage(source, 'websocket-peer')
      }
      socket.onerror = /** 结构说明（自动提取）：匿名回调；无显式参数；直接调用 clearTimeout、reject、Error。 */ () => { finish(new Error('WebSocket transport failed.')); if (this.socket === socket) onState('WebSocket transport failed.') }
      socket.onclose = /** 对端握手前关闭时也立即失败，避免等待残留超时。 */ () => { finish(new Error('WebSocket closed before connection completed.')); if (this.socket === socket) onState('closed') }
    })
  }
  /** 结构说明（自动提取）：send；输入 source、target；直接调用 Error、socket.send、stableNetworkJson；包含显式抛错路径。 */ async send(source: string, target = ''): Promise<void> { if (this.socket?.readyState !== WebSocket.OPEN) throw new Error('WebSocket is not connected.'); this.socket.send(target ? stableNetworkJson({ format: 'nova-network-route', version: 1, sender: this.context.networkingState.localPeerId, target, payload: source }) : source) }
  /** 结构说明（自动提取）：close；无显式参数；直接调用 socket.close；写入 socket。 */ async close(): Promise<void> { const socket = this.socket; this.socket = null; this.cancelOpening?.(); this.cancelOpening = null; if (socket) { socket.onopen = null; socket.onmessage = null; socket.onerror = null; socket.onclose = null; socket.close(1000, 'Nova_A session stopped') } }
}

import type { NetworkTransport, NetworkTransportContext } from '../runtime/networkSessionContracts'

export class NativeUdpTransport implements NetworkTransport {
  constructor(private readonly context:NetworkTransportContext) {}

  readonly kind = 'native-udp' as const
  private socketId: number | null = null
  private pollTimer: ReturnType<typeof setTimeout> | null = null
  private peers = new Map<string, string>()
  /** 结构说明（自动提取）：connect；输入 onMessage、onState；直接调用 Error、invoke、onState、poll；写入 socketId；等待异步结果；包含显式抛错路径。 */ async connect(onMessage: (source: string, peer: string) => void, onState: (state: string) => void): Promise<void> {
    if (typeof window === 'undefined' || !('__TAURI_INTERNALS__' in window)) throw new Error('Native UDP transport is available only in a Nova_A desktop player.')
    const { invoke } = await import('@tauri-apps/api/core')
    this.socketId = await invoke<number>('udp_open', { bindAddress: this.context.configuration.networking.bindAddress })
    const poll = /** 结构说明（自动提取）：poll；无显式参数；直接调用 invoke、onMessage、onState、String、globalThis.setTimeout；写入 pollTimer；包含循环处理；等待异步结果。 */ async () => {
      if (this.socketId === null) return
      try {
        const packets = await invoke<Array<{ source: string; payload: string }>>('udp_receive', { socketId: this.socketId, maximum: 64 })
        for (const packet of packets) onMessage(packet.payload, packet.source)
      } catch (error) { onState(error instanceof Error ? error.message : String(error)) }
      if (this.socketId !== null) this.pollTimer = globalThis.setTimeout(poll, 8)
    }
    onState('connected'); void poll()
  }
  /** 结构说明（自动提取）：send；输入 source、target；直接调用 Error、productionSettings.networking.endpoint.replace、peers.get、peers.values、slice 等；包含循环处理；等待异步结果；包含显式抛错路径。 */ async send(source: string, target = ''): Promise<void> {
    if (this.socketId === null) throw new Error('UDP socket is not open.')
    const { invoke } = await import('@tauri-apps/api/core')
    const configured = this.context.configuration.networking.endpoint.replace(/^udp:\/\//i, '')
    const mappedTarget = target ? this.peers.get(target) : undefined
    if (target && !mappedTarget) throw new Error('Native UDP target has not completed bounded peer admission.')
    const targets = mappedTarget ? [mappedTarget] : this.context.configuration.networking.role === 'client' ? [configured] : [...this.peers.values()]
    for (const destination of [...new Set(targets)].slice(0, this.context.configuration.networking.maxPeers)) {
      await invoke('udp_admit_peer', { socketId: this.socketId, target: destination })
      await invoke('udp_send', { socketId: this.socketId, target: destination, payload: source })
    }
  }
  /** 结构说明（自动提取）：close；无显式参数；直接调用 clearTimeout、invoke、peers.clear；写入 pollTimer、socketId；等待异步结果。 */ async close(): Promise<void> {
    if (this.pollTimer !== null) clearTimeout(this.pollTimer); this.pollTimer = null
    if (this.socketId !== null) { const { invoke } = await import('@tauri-apps/api/core'); await invoke('udp_close', { socketId: this.socketId }) }
    this.socketId = null; this.peers.clear()
  }
  /** 结构说明（自动提取）：bindPeer；输入 peerId、endpoint；直接调用 peers.set。 */ bindPeer(peerId: string, endpoint: string): void { if (peerId && endpoint && this.peers.size < this.context.configuration.networking.maxPeers) this.peers.set(peerId, endpoint) }
  /** 结构说明（自动提取）：unbindPeer；输入 peerId；直接调用 peers.get、peers.delete、catch、then。 */ unbindPeer(peerId: string): void {
    const endpoint = this.peers.get(peerId), socketId = this.socketId
    this.peers.delete(peerId)
    if (endpoint && socketId !== null) void import('@tauri-apps/api/core').then(/* 调用 invoke('udp_forget_peer', { socketId, target: endpoint }) 并返回调用结果。 */ ({ invoke }) => invoke('udp_forget_peer', { socketId, target: endpoint })).catch(/* 返回 undefined 的当前值。 */ () => undefined)
  }
}

import type { NetworkPlatformPorts, NetworkTransportContext } from '../runtime/networkSessionContracts'
import { safeId } from '../runtime/networkProductionValues'
import { openReviewedNetworkService } from '../runtime/networkServices'
import { LocalLobbyTransport, WebSocketTransport } from './webNetworkTransports'
import { NativeUdpTransport } from './nativeNetworkTransport'

export function createNetworkEpoch(): string {
  const random = typeof crypto !== 'undefined' && 'randomUUID' in crypto ? crypto.randomUUID() : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`
  return safeId(random, 80)
}

export function createNetworkNonce(sequence: number): string {
  const random = typeof crypto !== 'undefined' && 'getRandomValues' in crypto ? crypto.getRandomValues(new Uint32Array(2)) : new Uint32Array([Date.now() >>> 0, Math.floor(Math.random() * 0xffff_ffff)])
  return `${sequence.toString(36)}-${random[0].toString(36)}-${random[1].toString(36)}`.slice(0, 120)
}

function peerIdentity(playerName: string): string { const uuid = typeof crypto !== 'undefined' && 'randomUUID' in crypto ? crypto.randomUUID() : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`; return `${playerName.replace(/[^a-zA-Z0-9_.-]/g, '_').slice(0, 32)}-${uuid.slice(0, 12)}` }

export function createNetworkPlatformPorts():NetworkPlatformPorts {
  return Object.freeze({
    now:()=>performance.now(),wallNow:()=>Date.now(),
    setTimeout:(callback:()=>void,delay:number)=>globalThis.setTimeout(callback,delay),clearTimeout:(handle:ReturnType<typeof globalThis.setTimeout>)=>globalThis.clearTimeout(handle),
    createAbortController:()=>new AbortController(),abortError:(message:string)=>new DOMException(message,'AbortError'),
    createEpoch:createNetworkEpoch,createNonce:createNetworkNonce,peerIdentity,
    openService:openReviewedNetworkService,
    createTransport(kind:'local-loopback'|'websocket'|'native-udp',context:NetworkTransportContext) { return kind==='local-loopback'?new LocalLobbyTransport(context):kind==='native-udp'?new NativeUdpTransport(context):new WebSocketTransport(context) }
  })
}

import { reactive } from 'vue'
import { physicsState } from '../store/physics'
import { packageState, OFFICIAL_NETWORKING_PACKAGE_ID } from '../runtime/packages'
import { productionSettings } from '../runtime/production'
import { reportRecoverableError } from '../runtime/runtimeFaultRecords'
import { ProductionNetworkOwner } from '../runtime/productionNetworkOwner'
import { NetworkSessionOwner } from '../runtime/networkSessionOwner'
import { MultiplayerReplayOwner } from '../runtime/multiplayerReplayOwner'
import type { NetworkConfiguration, NetworkConfigurationHost } from '../runtime/networkSessionContracts'
import { createNetworkPlatformPorts } from '../platform/networkPlatformFactory'
import { getLegacyNetworkSessionOwnerRawState, installLegacyNetworkSessionOwnerPort } from '../runtime/networking'
import { getLegacyMultiplayerReplayOwnerRawState, installLegacyMultiplayerReplayOwnerPort } from '../runtime/networkReplay'
import { installLegacyProductionNetworkOwnerPort } from '../runtime/productionRuntime'

const networkingView=reactive(getLegacyNetworkSessionOwnerRawState())
const replayView=reactive(getLegacyMultiplayerReplayOwnerRawState())
const owners=new WeakMap<object,ProductionNetworkOwner>()
const sessions=new WeakMap<ProductionNetworkOwner,NetworkSessionOwner>()
let legacyOwner:ProductionNetworkOwner|null=null
interface EditorNetworkHost { readonly state:{world:NetworkConfigurationHost['world']};readEnabledPackageIds():string[] }
export function createEditorProductionNetworkOwner(suppliedHost:EditorNetworkHost,options:{legacyRoot:boolean;readConfiguration():NetworkConfiguration}):ProductionNetworkOwner {
  if(options.legacyRoot&&suppliedHost.state!==physicsState)throw new Error('PRODUCTION_NETWORK_LEGACY_ROOT_REQUIRED: The legacy bridge requires the Editor root state.')
  const world=suppliedHost.state.world
  const previous=options.legacyRoot?legacyOwner:owners.get(suppliedHost)
  if(previous?.world===world)return previous
  const host:NetworkConfigurationHost={world,readConfiguration(){
    if(suppliedHost.state.world!==world)throw new Error('PRODUCTION_NETWORK_WORLD_CHANGED: Recreate the Core after replacing its World.')
    return options.readConfiguration()
  }}
  const platform=createNetworkPlatformPorts()
  const replay=new MultiplayerReplayOwner(host,platform,options.legacyRoot?replayView:undefined)
  const session=new NetworkSessionOwner(host,platform,replay,options.legacyRoot?networkingView:undefined)
  const owner=new ProductionNetworkOwner(host,{
    packageId:OFFICIAL_NETWORKING_PACKAGE_ID,
    packageEnabled(id){return suppliedHost.readEnabledPackageIds().includes(id)},
    async loadSession(){return session},reportRecoverableError
  })
  sessions.set(owner,session)
  if(options.legacyRoot)legacyOwner=owner
  else owners.set(suppliedHost,owner)
  return owner
}
function getEditorProductionNetworkOwner():ProductionNetworkOwner {
  if(legacyOwner?.world===physicsState.world)return legacyOwner
  return createEditorProductionNetworkOwner({get state(){return physicsState},readEnabledPackageIds(){return packageState.installed.filter(item=>item.enabled&&item.project).map(item=>item.manifest.id)}},{legacyRoot:true,readConfiguration(){return productionSettings}})
}
function getEditorNetworkSessionOwner():NetworkSessionOwner { const owner=getEditorProductionNetworkOwner(),session=sessions.get(owner);if(!session)throw new Error('EDITOR_NETWORK_SESSION_MISSING');return session }
installLegacyProductionNetworkOwnerPort({getOwner:getEditorProductionNetworkOwner})
installLegacyNetworkSessionOwnerPort({stateView:networkingView,getOwner:getEditorNetworkSessionOwner})
installLegacyMultiplayerReplayOwnerPort({stateView:replayView,getOwner:()=>getEditorNetworkSessionOwner().replay})

/** Compatibility facade; the Editor registers its one explicit legacy Owner. */
import type { Entity } from '../world/Entity'
import type { InputSnapshot } from './input'
import { ProductionNetworkOwner } from './productionNetworkOwner'
import type { ProductionRemoteInputFrame } from './productionNetworkOwner'
type NetworkingModule=typeof import('./networking')
export type { ProductionRemoteInputFrame } from './productionNetworkOwner'
let provider:(()=>ProductionNetworkOwner)|null=null
export function installLegacyProductionNetworkOwnerPort(port:{getOwner:()=>ProductionNetworkOwner}):void { provider=port.getOwner }
export function requireLegacyProductionNetworkOwner():ProductionNetworkOwner {if(!provider)throw new Error('LEGACY_NETWORK_OWNER_REQUIRED: Install the Editor network bridge.');return provider()}
export function beginProductionRuntime(): void { return requireLegacyProductionNetworkOwner().beginProductionRuntime() }
export async function startProductionNetworking(): Promise<NetworkingModule> { await requireLegacyProductionNetworkOwner().startProductionNetworking();return import('./networking') }
export async function networkingModule(): Promise<NetworkingModule> { await requireLegacyProductionNetworkOwner().networkingModule();return import('./networking') }
export function productionNetworkContext(): { enabled: boolean; connected: boolean; authority: boolean; peerCount: number; localPeerId: string; role: string; tick: number } { return requireLegacyProductionNetworkOwner().productionNetworkContext() }
export function callProductionRpc(name: string, payload: unknown): boolean { return requireLegacyProductionNetworkOwner().callProductionRpc(name, payload) }
export function onProductionRpc(listener: (name: string, payload: unknown, context: { sender: string; tick: number }) => void): () => void { return requireLegacyProductionNetworkOwner().onProductionRpc(listener) }
export function onProductionSceneHandoff(listener: (sceneUuid: string, spawnTag: string, peerId: string) => void): () => void { return requireLegacyProductionNetworkOwner().onProductionSceneHandoff(listener) }
export function onProductionRemoteInput(listener: (frame: ProductionRemoteInputFrame) => void): () => void { return requireLegacyProductionNetworkOwner().onProductionRemoteInput(listener) }
export async function stopProductionNetworking(): Promise<void> { return requireLegacyProductionNetworkOwner().stopProductionNetworking() }
export function updateProductionRuntime(entities: Entity[], fixedDelta: number, input?: InputSnapshot, physicsChecksum = ''): void { return requireLegacyProductionNetworkOwner().updateProductionRuntime(entities, fixedDelta, input, physicsChecksum) }
export function stopProductionRuntime(): void { return requireLegacyProductionNetworkOwner().stopProductionRuntime() }

