/** 游戏脚本运行桥接：组织脚本实例和回调，将脚本命令应用到场景与各游戏子系统。 */
import type { GameplayWorldHost } from './gameplayWorldHost'
import type { PreparedRuntimeSceneTransition } from './runtimeSceneContracts'
