  /** 结构说明（自动提取）：acknowledgeBootstrap；输入 channel、sequence；直接调用 pending.get、pending.delete。 */ acknowledgeBootstrap(channel: string, sequence: number): boolean {
    const key = `*:${channel}:${sequence}`, pending = this.pending.get(key)
